<template><div v-if="store.ui.screen==='game'" class="campus-hud"><div class="wallet mc-panel"><b>{{account.guest?'游客漫游':`Lv.${e?.level||1} · ${account.user?.username}`}}</b><template v-if="e&&!account.guest"><span class="gold">金 {{e.gold_copper/10000}}</span><span>银 {{e.silver_copper/100}}</span><span>铜 {{e.copper}}</span><small>积分 {{e.points}} · 本级 {{e.progress}} / {{e.required}}</small><progress :value="e.progress" :max="e.required"></progress></template><small v-else>经济与社交需要登录</small><small>{{store.ui.hud.fps}} FPS · P95 {{store.ui.hud.frameP95||0}}ms · {{store.ui.hud.drawCalls||0}} calls</small></div><nav><button class="mc-btn small" @click="open('shop')">装扮商店</button><button class="mc-btn small" @click="open('campus')">校园生活</button><button class="mc-btn small" @click="open('social')">校园广场</button><button class="mc-btn small" @click="logout">退出</button></nav><p class="error" v-if="account.saveError">云存档：{{account.saveError}}</p></div>
<section v-if="account.tab==='shop'" class="campus-modal mc-panel"><header><h2>校园装扮铺</h2><button class="mc-btn" @click="close">关闭</button></header><p>金币买装扮，银铜添心意。各币种独立使用，不提供任何兑换。</p><p role="alert">{{error}}</p><div class="goods"><article v-for="item in e?.catalog" :key="item.id"><div class="item-icon">{{icons[item.id]||'✦'}}</div><h3>{{item.name}}</h3><p>{{item.currency==='gold_copper'?item.price/10000+' 金':item.currency==='silver_copper'?item.price/100+' 银':item.price+' 铜'}} · Lv.{{item.unlock.level}}</p><template v-if="item.consumable"><p>消耗品 · 库存 {{e.quantities?.[item.id]||0}} 件</p><button class="mc-btn" :disabled="busy||e.level<item.unlock.level" @click="buy(item.id)">购买 1 件</button><button class="mc-btn" :disabled="busy||!owned(item.id)" @click="equip(item.id)">使用 1 件</button></template><button v-else class="mc-btn" :disabled="busy||e.level<item.unlock.level" @click="owned(item.id)?equip(item.id):buy(item.id)">{{owned(item.id)?'使用装扮':'购买'}}</button></article></div></section>
<section v-if="account.tab==='campus'" class="campus-modal mc-panel"><header><h2>校园生活</h2><button class="mc-btn" @click="close">关闭</button></header><p>广东工业大学 · 广州</p><p>前往教学楼上课，到图书馆拍照，回宿舍布置自己的角落。</p><button class="mc-btn" @click="travel('school:gdut')">返回校门</button><button class="mc-btn" @click="travel('school:gdut-classroom')">前往教室</button><button class="mc-btn" @click="travel('school:gdut-dorm')">前往宿舍</button><button class="mc-btn" @click="travel('school:gdut-library')">前往图书馆</button></section></template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import {account,api,eventKey,refreshEconomy,logout} from '../campus/session.js'
import {store,toast} from '../game/store.js'
import {G} from '../game/instance.js'
import {equip as applyCosmetic} from '../campus/cosmetics.js'
const e=computed(()=>account.economy),error=ref(''),busy=ref(false),icons={cap:'🧢',frame:'▣',plant:'🌱',profile5:'✦','copper-border':'▤','silver-sticker':'✧'}
let timer
const pendingBuys=new Map()
function open(tab){if(account.lesson)return toast('请先离座结束本堂课');if(account.guest&&tab==='shop')return toast('登录后可使用商店');account.tab=tab;store.ui.panel='campus';G.game?.input.exitLock()}
function close(){account.tab=null;store.ui.panel=null}
const owned=id=>e.value?.inventory.includes(id)
async function buy(sku){if(busy.value)return;busy.value=true;const intent=account.user.id+':'+sku;const key=pendingBuys.get(intent)||eventKey();pendingBuys.set(intent,key);try{error.value='';await api('/shop/buy',{key,sku});pendingBuys.delete(intent);await refreshEconomy();toast('装扮已放入背包')}catch(err){if(err.status>=400&&err.status<500)pendingBuys.delete(intent);error.value=err.message}finally{busy.value=false}}
async function equip(sku){if(busy.value)return;busy.value=true;try{await applyCosmetic(sku)}finally{busy.value=false}}
async function travel(id){const game=G.game;if(game?.landmarks.byId[id]){const p=game.landmarks.toWorld(id,0,.4,id.includes('classroom')?4:12);close();await game.spawnAt({pos:p,yaw:0})}else toast('请在校园入口出生')}
async function tick(){if(account.guest||!account.user)return;try{account.identity=await api('/play/heartbeat',{});if(!account.identity.allowed){G.game?.stop();toast('今日游戏时间已结束，请退出账号','warn');store.ui.screen='menu';window.dispatchEvent(new Event('campus:blocked'))}await refreshEconomy()}catch(err){toast(err.message,'warn');G.game?.stop();store.ui.screen='menu';window.dispatchEvent(new Event('campus:blocked'))}}
onMounted(()=>{tick();timer=setInterval(tick,30000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<style>
.campus-hud{position:fixed;left:12px;bottom:82px;z-index:12;max-width:320px}.wallet{padding:12px;display:flex;flex-wrap:wrap;gap:10px;font-size:13px}.wallet b,.wallet small{width:100%}.gold{color:#ffdc75}.wallet progress{width:100%;height:7px;accent-color:#acd279}.campus-hud nav{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}.campus-modal{position:fixed;z-index:45;top:50%;left:50%;transform:translate(-50%,-50%);width:min(820px,94vw);max-height:88vh;overflow:auto;padding:24px;background:#1d292b}.campus-modal header{display:flex;align-items:center;justify-content:space-between;gap:12px}.campus-modal h2{color:#ffe3a1}.goods{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.goods article{padding:18px;border:2px solid #617366;background:#263633}.item-icon{font-size:36px;color:#b6cf91}.error{color:#ffb296}.campus-modal input,.campus-modal textarea,.campus-modal select{background:#111e23;color:#fff;border:2px solid #63786b;padding:10px;max-width:100%}@media(max-width:720px){.campus-hud{top:104px;bottom:auto;max-width:230px}.wallet{padding:6px;gap:5px;font-size:11px}.goods{grid-template-columns:repeat(2,1fr)}.campus-modal{padding:14px}}
</style>
